PRAGMA user_version=2;
CREATE TABLE IF NOT EXISTS schema_versions(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS migration_state(id INTEGER PRIMARY KEY CHECK(id=1),source_sha256 TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('MIGRATING','VERIFIED','PUBLISHED')),verification TEXT,started_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS migration_checkpoints(stage TEXT PRIMARY KEY,last_key INTEGER NOT NULL,records INTEGER NOT NULL,source_sha256 TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_inventory(name TEXT PRIMARY KEY,classification TEXT NOT NULL,record_count INTEGER NOT NULL,schema_sql TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence_objects(id INTEGER PRIMARY KEY,raw_sha256 TEXT NOT NULL UNIQUE CHECK(length(raw_sha256)=64),raw_size INTEGER NOT NULL CHECK(raw_size>=0),codec TEXT NOT NULL CHECK(codec IN ('deflate','raw')),payload BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS legacy_records(namespace TEXT NOT NULL,external_id TEXT NOT NULL,source_hash TEXT NOT NULL,evidence_id INTEGER NOT NULL REFERENCES evidence_objects(id),created_at TEXT NOT NULL,PRIMARY KEY(namespace,external_id)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS history_rows(id INTEGER PRIMARY KEY,row_hash TEXT NOT NULL UNIQUE CHECK(length(row_hash)=64),kind TEXT NOT NULL,instrument_id TEXT NOT NULL,session TEXT NOT NULL,raw_size INTEGER NOT NULL,codec TEXT NOT NULL,payload BLOB NOT NULL,projection_version TEXT NOT NULL,projection_hash TEXT NOT NULL,
 open TEXT,high TEXT,low TEXT,close TEXT,amount_cny TEXT,volume_shares TEXT,turnover_fraction TEXT,comparable_open TEXT,comparable_high TEXT,comparable_low TEXT,comparable_close TEXT,comparable_basis TEXT,quality TEXT,limit_up TEXT,limit_down TEXT,limit_verified TEXT,limit_applicable TEXT,reference_prev_close TEXT,source_refs TEXT,event_time TEXT,source_published_at TEXT,first_seen_at TEXT,ingested_at TEXT,
 effective_from TEXT,effective_to TEXT,listed_on TEXT,exchange TEXT,board TEXT,security_type TEXT,st TEXT,suspended TEXT,delisting_period TEXT);
CREATE INDEX IF NOT EXISTS history_security_window ON history_rows(instrument_id,session,kind,id);
CREATE INDEX IF NOT EXISTS history_session_cross_section ON history_rows(session,kind,instrument_id,id);
CREATE TABLE IF NOT EXISTS partitions(id INTEGER PRIMARY KEY,partition_hash TEXT NOT NULL UNIQUE CHECK(length(partition_hash)=64));
CREATE TABLE IF NOT EXISTS partition_members(partition_id INTEGER NOT NULL REFERENCES partitions(id),row_id INTEGER NOT NULL REFERENCES history_rows(id),PRIMARY KEY(partition_id,row_id)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS members_row ON partition_members(row_id,partition_id);
CREATE TABLE IF NOT EXISTS snapshots(snapshot_id TEXT PRIMARY KEY,namespace TEXT NOT NULL,evidence_id INTEGER NOT NULL REFERENCES evidence_objects(id),observation_date TEXT NOT NULL,cutoff TEXT,history_ref TEXT,coverage_type TEXT);
CREATE TABLE IF NOT EXISTS snapshot_members(snapshot_id TEXT NOT NULL REFERENCES snapshots(snapshot_id),kind TEXT NOT NULL,ordinal INTEGER NOT NULL,evidence_id INTEGER NOT NULL REFERENCES evidence_objects(id),instrument_id TEXT,session TEXT,PRIMARY KEY(snapshot_id,kind,ordinal)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS snapshot_members_instrument ON snapshot_members(snapshot_id,instrument_id,kind,session);
CREATE TABLE IF NOT EXISTS snapshot_partitions(snapshot_id TEXT NOT NULL REFERENCES snapshots(snapshot_id),partition_id INTEGER NOT NULL REFERENCES partitions(id),session TEXT NOT NULL,row_count INTEGER NOT NULL CHECK(row_count>=0),PRIMARY KEY(snapshot_id,partition_id)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS source_receipts(snapshot_id TEXT NOT NULL REFERENCES snapshots(snapshot_id),ordinal INTEGER NOT NULL,receipt_id TEXT NOT NULL,content_hash TEXT,provider TEXT,dataset TEXT,status TEXT,event_time TEXT,source_published_at TEXT,first_seen_at TEXT,ingested_at TEXT,evidence_id INTEGER NOT NULL REFERENCES evidence_objects(id),projection_hash TEXT NOT NULL,PRIMARY KEY(snapshot_id,ordinal)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS receipt_scope_identity ON source_receipts(snapshot_id,receipt_id,content_hash);
CREATE TABLE IF NOT EXISTS legacy_result_headers(legacy_id TEXT NOT NULL,namespace TEXT NOT NULL,strategy_id TEXT,input_id TEXT,observation_date TEXT,cutoff TEXT,evidence_id INTEGER NOT NULL REFERENCES evidence_objects(id),PRIMARY KEY(namespace,legacy_id)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS result_list ON legacy_result_headers(namespace,observation_date,legacy_id);
CREATE TABLE IF NOT EXISTS legacy_result_items(run_id TEXT NOT NULL,instrument_id TEXT NOT NULL,strategy_id TEXT NOT NULL,detail_id TEXT NOT NULL,PRIMARY KEY(run_id,instrument_id,strategy_id)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS archived_table_rows(table_name TEXT NOT NULL,legacy_key TEXT NOT NULL,revision TEXT NOT NULL,evidence_id INTEGER NOT NULL REFERENCES evidence_objects(id),PRIMARY KEY(table_name,legacy_key,revision)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS historical_jobs(job_id TEXT NOT NULL,revision INTEGER NOT NULL,state TEXT NOT NULL,kind TEXT NOT NULL,updated_at TEXT NOT NULL,evidence_id INTEGER NOT NULL REFERENCES evidence_objects(id),executable INTEGER NOT NULL DEFAULT 0 CHECK(executable=0),PRIMARY KEY(job_id,revision)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS external_references(owner_namespace TEXT NOT NULL,owner_id TEXT NOT NULL,field TEXT NOT NULL,target TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('RESOLVED','UNRESOLVED')),PRIMARY KEY(owner_namespace,owner_id,field,target)) WITHOUT ROWID;
